import React from "react";
import { Check } from "lucide-react";
import Reveal from "./Reveal";
import { COLORS, FONT_DISPLAY } from "../constants/theme";

export default function FinalCTA({ emailSent, setEmailSent }) {
  return (
    <section style={{ background: COLORS.surfaceStrong, color: COLORS.textOnStrong, padding: "110px 0" }} className="px-6 md:px-10">
      <div style={{ maxWidth: 700, margin: "0 auto", textAlign: "center" }}>
        <Reveal>
          <h2 style={{ fontFamily: FONT_DISPLAY, fontSize: "clamp(32px, 5vw, 54px)", lineHeight: 1.1, marginBottom: 20 }}>
            Your piece is <span style={{ fontStyle: "italic" }}>one click</span> away.
          </h2>
          <p style={{ fontSize: 15.5, color: COLORS.textOnStrongMuted, marginBottom: 34 }}>
            New pieces, restocks, and notes from the workshop — a few times a month, nothing more.
          </p>
          {!emailSent ? (
            <form
              onSubmit={(e) => {
                e.preventDefault();
                setEmailSent(true);
              }}
              className="flex flex-col sm:flex-row"
              style={{ gap: 12, maxWidth: 420, margin: "0 auto" }}
            >
              <input
                required
                type="email"
                placeholder="you@email.com"
                style={{
                  flex: 1,
                  background: "transparent",
                  border: `1px solid ${COLORS.borderOnStrong}`,
                  color: COLORS.textOnStrong,
                  padding: "14px 16px",
                  fontSize: 14,
                  outline: "none",
                }}
              />
              <button
                type="submit"
                style={{ background: COLORS.gold, color: COLORS.surfaceStrong, border: "none", padding: "14px 24px", fontSize: 14, letterSpacing: "0.03em" }}
              >
                Subscribe
              </button>
            </form>
          ) : (
            <p style={{ display: "inline-flex", alignItems: "center", gap: 8, color: COLORS.gold, fontSize: 15 }}>
              <Check size={18} /> You're on the list.
            </p>
          )}
        </Reveal>
      </div>
    </section>
  );
}
